package com.pointverse.app;

import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;
import java.util.function.Consumer;

/** Explicit bidirectional, versioned sync. Cloud versions are immutable; deletions never propagate automatically. */
final class CloudSync {
    interface Remote {JSONObject json(String path,String method,String token,JSONObject body)throws Exception;void upload(String token,String hash,File file)throws Exception;void download(String path,String token,File file,long max,String hash,long bytes)throws Exception;}
    static final class Report {int uploaded,added,updated,conflicts,skipped,deleted,failed;final List<String> errors=new ArrayList<>();String message(){String result="上传 "+uploaded+" 条 · 新增 "+added+" 条 · 更新 "+updated+" 条\n保留云端副本 "+conflicts+" 条 · 已同步/跳过 "+(skipped+deleted)+" 条";if(failed>0)result+="\n失败 "+failed+" 条，可再次同步重试\n"+String.join("\n",errors);return result;}void error(String title,Exception e){failed++;if(errors.size()<5)errors.add(title+"："+(e instanceof IOException?e.getMessage():"内容未完成同步，请重试"));}}
    private final PointStore store;private final Remote remote;private java.util.function.BooleanSupplier active=()->true;
    CloudSync guarded(java.util.function.BooleanSupplier active){this.active=active;return this;}
    CloudSync(PointStore store){this(store,new Remote(){public JSONObject json(String path,String method,String token,JSONObject body)throws Exception{return NetworkModel.api(path,method,token,body);}public void upload(String token,String hash,File file)throws Exception{NetworkModel.uploadFile(token,hash,file);}public void download(String path,String token,File file,long max,String hash,long bytes)throws Exception{NetworkModel.downloadFile(path,token,file,max,hash,bytes);}});}
    CloudSync(PointStore store,Remote remote){this.store=store;this.remote=remote;}
    interface Work<T>{T run()throws Exception;}
    private <T>T retry(Work<T> work)throws Exception {for(int attempt=0;;attempt++){check();try{return work.run();}catch(NetworkModel.ServiceException e){if(attempt>=3||!Arrays.asList(502,503,504).contains(e.status))throw e;Thread.sleep(1000L<<attempt);}}}
    private JSONObject call(String path,String method,String token,JSONObject body)throws Exception {return retry(()->remote.json(path,method,token,body));}
    static String hash(byte[] bytes)throws Exception {java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");StringBuilder value=new StringBuilder();for(byte b:digest.digest(bytes))value.append(String.format(Locale.ROOT,"%02x",b&255));return value.toString();}
    static JSONObject merged(JSONObject original,JSONObject changes)throws Exception {JSONObject result=new JSONObject(original.toString());for(Iterator<String> keys=changes.keys();keys.hasNext();){String key=keys.next();result.put(key,changes.get(key));}return result;}
    static JSONArray rows(JSONObject payload,String key){JSONArray a=payload.optJSONArray(key);return a==null?new JSONArray():a;}
    static JSONObject find(JSONArray array,String id){for(int i=0;i<array.length();i++){JSONObject o=array.optJSONObject(i);if(o!=null&&id.equalsIgnoreCase(o.optString("id")))return o;}return new JSONObject();}
    static void upsert(JSONArray rows,JSONObject row)throws Exception {String id=row.optString("id");for(int i=0;i<rows.length();i++)if(id.equalsIgnoreCase(rows.getJSONObject(i).optString("id"))){rows.put(i,row);return;}rows.put(row);}
    JSONObject snapshot(PointStore.Point point)throws Exception {android.database.sqlite.SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{JSONObject result=buildSnapshot(store.get(point.id));db.setTransactionSuccessful();return result;}finally{db.endTransaction();}}
    private JSONObject buildSnapshot(PointStore.Point p)throws Exception {
        String cached=store.snapshotCache(p.id,p.revision);if(cached!=null)return new JSONObject(cached);
        JSONObject origin=CloudRestore.source(store,p.id),base=origin.optJSONObject("manifest");if(base==null)base=new JSONObject();JSONObject payload=base.optJSONObject("payload");payload=payload==null?new JSONObject():new JSONObject(payload.toString());
        String message=origin.optString("primary_message");if(message.isEmpty())message=UUID.nameUUIDFromBytes((p.id+"message").getBytes(StandardCharsets.UTF_8)).toString();String audioId=origin.optString("primary_audio");if(audioId.isEmpty())audioId=p.id;
        double timestamp=p.created/1000.0;JSONArray assets=new JSONArray(),audio=rows(payload,"audio_assets"),messages=rows(payload,"messages"),transcripts=rows(payload,"transcripts");JSONArray images=new JSONArray(),localImages=store.rows("images",p.id);Set<String> currentImages=new HashSet<>();for(int i=0;i<localImages.length();i++)currentImages.add(localImages.getJSONObject(i).getString("id"));
        JSONArray originalAssets=rows(base,"assets");JSONObject sourceFiles=origin.optJSONObject("files");for(int i=0;i<originalAssets.length();i++){JSONObject asset=originalAssets.getJSONObject(i);String id=asset.getString("id");if(asset.getString("kind").equals("audio")||currentImages.contains(id)||find(rows(payload,"point_images"),id).length()==0)assets.put(asset);}
        JSONObject point=merged(find(rows(payload,"points"),p.id),new JSONObject().put("id",p.id).put("head_revision",p.revision).put("created_at",timestamp).put("accepted_title",p.title).put("modality",p.path==null?"text":"audio"));
        upsert(messages,merged(find(messages,message),new JSONObject().put("id",message).put("point_id",p.id).put("sequence",1).put("role","user").put("user_text",p.path==null?p.body:find(messages,message).optString("user_text","")).put("created_at",timestamp)));
        if(p.path!=null){File file=store.audioFile(p);String digest=LocalSpeech.hash(file);upsert(assets,asset(audioId,digest,file.length(),"audio"));upsert(audio,merged(find(audio,audioId),new JSONObject().put("id",audioId).put("message_id",message).put("sha256",digest).put("byte_count",file.length()).put("state","available").put("relative_path",p.path).put("duration_ms",p.duration)));JSONObject t=new JSONObject();int index=-1;for(int i=0;i<transcripts.length();i++)if(audioId.equalsIgnoreCase(transcripts.getJSONObject(i).optString("asset_id"))){t=transcripts.getJSONObject(i);index=i;break;}t.put("asset_id",audioId).put("engine_text",p.machine).put("user_text",p.edited==1?p.body:JSONObject.NULL);if(index>=0)transcripts.put(index,t);else transcripts.put(t);}
        for(int i=0;i<localImages.length();i++){JSONObject image=localImages.getJSONObject(i);File file=new File(store.imageDirectory(),image.getString("path"));String digest=LocalSpeech.hash(file);upsert(assets,asset(image.getString("id"),digest,file.length(),"image"));JSONObject row=merged(find(rows(payload,"point_images"),image.getString("id")),image);row.put("point_id",p.id).put("sha256",digest).put("byte_count",file.length()).put("recognized_text",image.optString("caption")).put("model_id",image.optString("model"));row.remove("path");images.put(row);}
        JSONArray chat=store.rows("conversation",p.id);int sequence=1;for(int i=0;i<messages.length();i++)sequence=Math.max(sequence,messages.getJSONObject(i).optInt("sequence")+1);for(int i=0;i<chat.length();i++){JSONObject m=chat.getJSONObject(i),old=find(messages,m.getString("id"));JSONObject row=merged(old,new JSONObject().put("id",m.getString("id")).put("point_id",p.id).put("sequence",old.optInt("sequence",sequence++)).put("role",m.getString("role")).put("user_text",m.getString("text")).put("model_id",m.getString("model")).put("created_at",m.getLong("created")/1000.0));upsert(messages,row);}
        List<JSONObject> orderedMessages=new ArrayList<>();for(int i=0;i<messages.length();i++)if(!message.equals(messages.getJSONObject(i).optString("id")))orderedMessages.add(messages.getJSONObject(i));orderedMessages.sort(Comparator.comparingInt(row->row.optInt("sequence")));JSONArray normalizedMessages=new JSONArray().put(find(messages,message).put("sequence",1));int order=2;for(JSONObject row:orderedMessages)normalizedMessages.put(row.put("sequence",order++));messages=normalizedMessages;
        JSONObject nativePoint=new JSONObject();for(String field:new String[]{"body","machine","summary","speaker","voice","domain","topic","project","expression","manual","locale","analysis","title_source","title_model"}){android.database.Cursor c=store.getReadableDatabase().rawQuery("SELECT "+field+" FROM points WHERE id=?",new String[]{p.id});try{if(c.moveToFirst())nativePoint.put(field,c.getString(0));}finally{c.close();}}nativePoint.put("edited",p.edited).put("title_edited",p.titleEdited).put("title_version",p.titleVersion);
        JSONArray candidates=new JSONArray(),nativeCandidates=store.rows("candidates",p.id);for(int i=0;i<nativeCandidates.length();i++){JSONObject candidate=nativeCandidates.getJSONObject(i);candidates.put(merged(find(rows(payload,"transcription_candidates"),candidate.getString("id")),candidate));}
        JSONArray relations=new JSONArray();try(android.database.Cursor c=store.getReadableDatabase().rawQuery("SELECT source,target,type FROM relations WHERE source=? OR target=?",new String[]{p.id,p.id})){while(c.moveToNext())relations.put(new JSONObject().put("source",c.getString(0)).put("target",c.getString(1)).put("type",c.getString(2)));}payload.put("android_relations",relations);
        payload.put("points",new JSONArray().put(point)).put("messages",messages).put("audio_assets",audio).put("point_images",images).put("transcripts",transcripts).put("transcription_candidates",candidates).put("manifestations",store.rows("manifestations",p.id)).put("android_point",nativePoint);
        JSONObject manifest=new JSONObject().put("format_version",1).put("point_id",p.id).put("revision",p.revision).put("title",p.title).put("preview",TitleGeneration.prefix(p.effective(),500)).put("created_at",timestamp).put("assets",assets).put("payload",payload);if(manifest.toString().getBytes(StandardCharsets.UTF_8).length>4*1024*1024)throw new IOException("单条想法超过云端同步大小限制");store.cacheSnapshot(p.id,p.revision,manifest.toString());return manifest;
    }
    private JSONObject asset(String id,String hash,long bytes,String kind)throws Exception{return new JSONObject().put("id",id).put("sha256",hash).put("byte_count",bytes).put("kind",kind);}
    void upload(PointStore.Point p,String token)throws Exception {upload(p,"",token);}
    boolean upload(PointStore.Point p,String account,String token)throws Exception {
        check();JSONObject manifest=snapshot(p);String digest=hash(manifest.toString().getBytes(StandardCharsets.UTF_8));if(!account.isEmpty()&&CloudRestore.seen(store,account,p.id,digest))return false;
        Map<String,File> files=new HashMap<>();if(p.path!=null){File audio=store.audioFile(store.get(p.id));files.put(LocalSpeech.hash(audio),audio);}JSONArray images=store.rows("images",p.id);for(int i=0;i<images.length();i++){File image=new File(store.imageDirectory(),images.getJSONObject(i).getString("path"));files.put(LocalSpeech.hash(image),image);}JSONObject source=CloudRestore.source(store,p.id).optJSONObject("files");if(source!=null)for(Iterator<String> keys=source.keys();keys.hasNext();){File file=new File(store.audio.getParentFile(),source.getString(keys.next()));if(file.isFile())files.put(LocalSpeech.hash(file),file);}
        JSONArray assets=manifest.getJSONArray("assets");for(int i=0;i<assets.length();i++){check();JSONObject a=assets.getJSONObject(i);File file=files.get(a.getString("sha256"));if(file==null||file.length()!=a.getLong("byte_count"))throw new IOException("本地附件缺失或校验失败");if(file.length()>128L*1024*1024)throw new IOException("附件超过 128 MB");boolean exists=false;try{remote.json("/v1/sync/assets/"+a.getString("sha256"),"HEAD",token,null);exists=true;}catch(NetworkModel.ServiceException error){if(!Arrays.asList(404,405,501,502,503,504).contains(error.status))throw error;}if(!exists)retry(()->{remote.upload(token,a.getString("sha256"),file);return true;});}
        check();JSONObject committed=call("/v1/sync/points","POST",token,manifest);String hash=CloudRestore.hash(committed.getString("manifest_hash"));if(!CloudRestore.uuid(committed.getString("point_id")).equals(p.id))throw new IOException("云端确认结果不一致");if(!account.isEmpty())CloudRestore.mark(store,account,p.id,hash,p.id,manifest.getInt("revision"));return true;
    }
    JSONArray versions(String token)throws Exception {JSONArray all=new JSONArray();String cursor="";Set<String> cursors=new HashSet<>();do{check();JSONObject page=call("/v1/sync/points"+(cursor.isEmpty()?"":"?cursor="+java.net.URLEncoder.encode(cursor,"UTF-8")),"GET",token,null);JSONArray items=page.getJSONArray("items");for(int i=0;i<items.length();i++){JSONObject v=items.getJSONObject(i);CloudRestore.uuid(v.getString("point_id"));CloudRestore.hash(v.getString("manifest_hash"));all.put(v);}cursor=page.optString("next_cursor");if(!cursor.isEmpty()&&!cursors.add(cursor))throw new IOException("云端分页异常，请重试");}while(!cursor.isEmpty());return all;}
    CloudRestore.Result download(JSONObject version,String account,String token)throws Exception {return download(version,account,token,false);}
    CloudRestore.Result download(JSONObject version,String account,String token,boolean asCopy)throws Exception {
        String id=CloudRestore.uuid(version.getString("point_id")),digest=CloudRestore.hash(version.getString("manifest_hash"));if(!asCopy&&CloudRestore.seen(store,account,id,digest))return new CloudRestore.Result(id,"skipped");File temp=Files.createTempDirectory(store.cloudDirectory().toPath(),"incoming-").toFile();try{File manifestFile=new File(temp,"manifest.json");retry(()->{remote.download("/v1/sync/points/"+id+"/versions/"+digest,token,manifestFile,4L*1024*1024,digest,-1);return true;});if(!LocalSpeech.hash(manifestFile).equals(digest))throw new IOException("云端版本校验失败");JSONObject manifest=new JSONObject(new String(Files.readAllBytes(manifestFile.toPath()),StandardCharsets.UTF_8));CloudRestore.validate(manifest);if(!CloudRestore.uuid(manifest.getString("point_id")).equals(id))throw new IOException("下载版本不一致");Map<String,File> files=new HashMap<>();JSONArray assets=manifest.getJSONArray("assets");long required=0;for(int i=0;i<assets.length();i++)required+=assets.getJSONObject(i).getLong("byte_count");if(required>0&&store.cloudDirectory().getUsableSpace()<required*3+16L*1024*1024)throw new IOException("本机空间不足，下载未改变现有内容");for(int i=0;i<assets.length();i++){check();JSONObject a=assets.getJSONObject(i);String hash=a.getString("sha256");if(files.containsKey(hash))continue;File file=new File(temp,hash);retry(()->{remote.download("/v1/sync/assets/"+hash,token,file,128L*1024*1024,hash,a.getLong("byte_count"));return true;});files.put(hash,file);}check();return CloudRestore.install(store,account,digest,manifest,files,asCopy);}finally{PointStore.removeTree(temp);}}
    Report uploadAll(String account,String token,Consumer<String> progress)throws Exception {Report result=new Report();List<PointStore.Point> points=store.list("");int count=0;for(PointStore.Point point:points){check();progress.accept("正在上传 "+(++count)+" / "+points.size());try{if(upload(point,account,token))result.uploaded++;else result.skipped++;}catch(Exception e){check();if(e instanceof NetworkModel.ServiceException&&Arrays.asList(401,403).contains(((NetworkModel.ServiceException)e).status))throw e;result.error(point.title,e);}}return result;}
    Report downloadAll(String account,String token,Consumer<String> progress)throws Exception {Report result=new Report();JSONArray all=versions(token);Set<String> visited=new HashSet<>();List<JSONObject> latest=new ArrayList<>();for(int i=0;i<all.length();i++)if(visited.add(all.getJSONObject(i).getString("point_id").toLowerCase(Locale.ROOT)))latest.add(all.getJSONObject(i));int count=0;for(JSONObject version:latest){check();progress.accept("正在下载 "+(++count)+" / "+latest.size());try{CloudRestore.Result item=download(version,account,token);switch(item.kind){case "added":result.added++;break;case "updated":result.updated++;break;case "conflict":result.conflicts++;break;case "deleted":result.deleted++;break;default:result.skipped++;}}catch(Exception e){check();if(e instanceof NetworkModel.ServiceException&&Arrays.asList(401,403).contains(((NetworkModel.ServiceException)e).status))throw e;result.error(version.optString("title"),e);}}return result;}
    static JSONArray extraAudio(PointStore store,String id)throws Exception {JSONObject source=CloudRestore.source(store,id),manifest=source.optJSONObject("manifest"),files=source.optJSONObject("files");JSONArray result=new JSONArray();if(manifest==null||files==null)return result;JSONObject data=manifest.getJSONObject("payload");JSONArray audio=rows(data,"audio_assets"),transcripts=rows(data,"transcripts");for(int i=0;i<audio.length();i++){JSONObject row=audio.getJSONObject(i);String asset=row.optString("id");if(asset.equals(source.optString("primary_audio"))||!files.has(asset))continue;String text="";for(int n=0;n<transcripts.length();n++){JSONObject t=transcripts.getJSONObject(n);if(asset.equals(t.optString("asset_id")))text=t.isNull("user_text")?t.optString("engine_text"):t.optString("user_text",t.optString("engine_text"));}result.put(new JSONObject().put("path",files.getString(asset)).put("text",text).put("duration",row.optLong("duration_ms",0)));}return result;}
    private void check()throws IOException {if(store.getDatabaseName().equals(DemoData.DATABASE)||store.getDatabaseName().matches("test-points-[a-f0-9-]{36}\\.db"))throw new IOException("测试库不参与云端同步");if(!active.getAsBoolean())throw new IOException("账户或模式已改变，同步已停止");if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("同步已暂停，已完成的内容保留");}
}
